    """Eventos existentes herdam a categoria do próprio inventário.

    Todos os inventários existentes recebem Lubrificantes (default do AddField).
    Eventos do módulo cíclico (sem inventário) permanecem com categoria vazia.
    Nenhum registro é apagado.
    """
    Inventario = apps.get_model('inventario', 'Inventario')
    Evento = apps.get_model('inventario', 'InventarioAuditoriaEvento')
    from django.db.models import OuterRef, Subquery

    Evento.objects.filter(inventario__isnull=False).update(
        categoria=Subquery(
            Inventario.objects.filter(pk=OuterRef('inventario_id')).values('categoria')[:1]
        )
    )


